@SQL
SELECT * FROM customers;

-- only the columns you need
SELECT name, city FROM customers;

@SQL
-- numbers need no quotes; only three rows come back
SELECT name, price
FROM products
WHERE price > 200;

@SQL
-- exact match on text
SELECT name, city
FROM customers
WHERE city = 'Lahore';

-- pattern match: % means any characters after the A
SELECT name
FROM customers
WHERE name LIKE 'A%';

@SQL
-- returns 1002 only: 1005 is also customer 2, but it is pending
SELECT order_id, customer_id, status
FROM orders
WHERE status = 'paid' AND customer_id = 2;

@SQL
SELECT name, price
FROM products
ORDER BY price DESC
LIMIT 3;

@SQL
-- largest first: Stapler 700, Register 400, Pen pack 250
SELECT name, price
FROM products
ORDER BY price DESC
LIMIT 3;

@SQL
SELECT COUNT(*) AS orders,
       SUM(quantity * unit_price) AS sales
FROM order_items;

@SQL
-- HAVING runs after the groups are made, so it can filter on a SUM
SELECT customer_id, COUNT(*) AS orders
FROM orders
GROUP BY customer_id
HAVING COUNT(*) > 1;

@SQL
SELECT customer_id, COUNT(*) AS orders
FROM orders
GROUP BY customer_id
HAVING COUNT(*) > 1;

@SQL
SELECT o.order_id, c.name, c.city, o.order_date
FROM orders AS o
INNER JOIN customers AS c
  ON o.customer_id = c.customer_id;

@SQL
SELECT c.name, COUNT(o.order_id) AS orders
FROM customers AS c
LEFT JOIN orders AS o
  ON c.customer_id = o.customer_id
GROUP BY c.name;

@SQL
SELECT name, price
FROM products
WHERE price > (SELECT AVG(price) FROM products);

@SQL
SELECT name, city
FROM customers
WHERE customer_id IN (
  SELECT customer_id
  FROM orders
  GROUP BY customer_id
  HAVING COUNT(*) > 1
);

@SQL
-- Step 1: look first
SELECT * FROM orders WHERE order_id = 1005;

-- Step 2: change it
UPDATE orders
SET status = 'paid'
WHERE order_id = 1005;

@SQL
BEGIN TRANSACTION;
UPDATE products SET stock = stock - 3 WHERE product_id = 3;
SELECT product_id, stock FROM products WHERE product_id = 3;
-- stock is now 9, which is correct
COMMIT;

@SQL
