@SQL
CREATE INDEX idx_orders_customer
ON orders (customer_id);

@SQL
-- slow: the function hides the column from the index
SELECT * FROM orders WHERE YEAR(order_date) = 2026;

-- faster: compare the column to a range
SELECT order_id FROM orders
WHERE order_date >= '2026-01-01'
  AND order_date < '2027-01-01';

@SQL
-- the safe order of work: WHERE first, then the rest
DELETE FROM orders WHERE order_id = 1005;

-- this one empties the whole table
-- DELETE FROM orders;

@SQL
-- count rows
SELECT COUNT(*) FROM orders;

-- filter and sort
SELECT name, price FROM products
WHERE price BETWEEN 100 AND 500
ORDER BY price DESC;

-- group and filter groups
SELECT customer_id, COUNT(*) AS n
FROM orders
GROUP BY customer_id
HAVING COUNT(*) > 1;

-- join with a left join to keep unmatched rows
SELECT c.name, COUNT(o.order_id) AS n
FROM customers c
LEFT JOIN orders o ON o.customer_id = c.customer_id
GROUP BY c.name;

-- safe change
BEGIN;
UPDATE products SET stock = stock - 1 WHERE product_id = 1;
COMMIT;
